-- Scenario 73d: SAP republishes MAINT_NOTIFICATION with DOWNTIMEHOURS as text instead of a number.
-- Expected guarded: G1 - the L1 cast DOWNTIMEHOURS::number(10,2) keeps L2 numeric; drift TYPE_CHANGED (WARNING).
-- Unguarded: the text type flows into the DT - see 75_observe.sql.
create or replace table {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION_V2 as
select MAINTENANCENOTIFICATION, EQUIPMENT, NOTIFICATIONTYPE, PRIORITY, CREATEDON,
       to_varchar(DOWNTIMEHOURS) as DOWNTIMEHOURS, NOTIFICATIONTEXT
from {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION;
alter table {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION swap with {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION_V2;
drop table {{DEMO_L0}}.PUBLISHER.MAINT_NOTIFICATION_V2;

insert into {{DEMO_DB}}.CONTROL.SCHEMA_CHANGE_LOG (SCENARIO, EVENT, GUARDRAIL, DETAIL, SOURCE)
values ('73d', 'SCENARIO_RUN', null, 'SAP republished MAINT_NOTIFICATION with DOWNTIMEHOURS as VARCHAR (was NUMBER(10,2))', 'PRESENTER');
